changeSet.sql:
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS content_generated (
    id uuid DEFAULT uuid_generate_v4() PRIMARY KEY,
    content text,
    metadata json,
    embedding vector(1024)
);
CREATE INDEX IF NOT EXISTS content_generated_embedding_idx
    ON content_generated USING HNSW (embedding vector_cosine_ops);

CREATE TABLE IF NOT EXISTS chatbot_knowledge_base (
    id uuid DEFAULT uuid_generate_v4() PRIMARY KEY,
    content text,
    metadata json,
    embedding vector(1024)
);
CREATE INDEX IF NOT EXISTS chatbot_knowledge_base_embedding_idx
    ON chatbot_knowledge_base USING HNSW (embedding vector_cosine_ops);
